const fs = require('fs');
const raw = Buffer.from($input.first().binary.config.data, 'base64').toString('utf8');
const cfg = JSON.parse(raw);
const ts = new Date().toISOString();
const decisionPath = '/opt/ec2-autoscaler/logs/decisions.jsonl';

if (!cfg.enabled) {
  const rec = {
    ts,
    action: 'DECISION',
    instance_id: null,
    reason: 'n8n_view_enabled_false',
    evidence: {},
    thresholds: { scale_out: cfg.scale_out, scale_in: cfg.scale_in },
    windows: { scale_out_window_minutes: cfg.scale_out.window_minutes, scale_in_window_minutes: cfg.scale_in.window_minutes },
    min_running: cfg.min_running,
    running_count_before: null,
    running_count_after: null,
    tags: cfg.tag_filter
  };
  fs.appendFileSync(decisionPath, JSON.stringify(rec) + '\n');
}

return [{ json: { enabled: !!cfg.enabled, ts } }];
